// Generated by MythAgentic. Turns the page's assistant section into a side panel that a
// launcher button opens from any page, and adds a small "Ask" bar right at each part of the
// page the assistant was placed for (marked data-agent-spot by the pack builder).
//
// Nothing here talks to a model. Buttons only open the panel and, at most, type a question
// into the chat and press Send, exactly as the visitor could.

const OPEN_KEY = "mythagentic-dock-open";
const section = typeof document === "undefined" ? null : document.querySelector("#assistant");

/** sessionStorage can throw (private mode, blocked storage); the panel works without it. */
function remember(open) {
  try { sessionStorage.setItem(OPEN_KEY, open ? "1" : "0"); } catch { /* not kept */ }
}
function remembered() {
  try { return sessionStorage.getItem(OPEN_KEY) === "1"; } catch { return false; }
}

/**
 * The site's own button colour, so the launcher and the Ask bars look like part of the site.
 * Only a colour that white text can sit on (contrast 4.5:1 or more) is used.
 */
function brandColour() {
  const lum = (rgb) => {
    const c = rgb.map((v) => { const s = v / 255; return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4; });
    return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
  };
  for (const el of document.querySelectorAll("header a, header button, nav a, main a, main button, a, button")) {
    if (el.closest("#assistant, .agent-hook, .agent-launcher")) continue;
    const bg = getComputedStyle(el).backgroundColor.match(/[\d.]+/g)?.map(Number);
    if (!bg || (bg.length === 4 && bg[3] < 0.8)) continue;
    const contrast = 1.05 / (lum(bg.slice(0, 3)) + 0.05);
    if (contrast >= 4.5) return `rgb(${bg.slice(0, 3).join(",")})`;
  }
  return "";
}

/** Waits for the runtime's chat input, which appears once the assistant has booted. */
async function chatInput(ms = 6000) {
  const start = Date.now();
  while (Date.now() - start < ms) {
    const input = document.querySelector("#ns-input");
    if (input) return input;
    await new Promise((r) => setTimeout(r, 120));
  }
  return null;
}

export class AssistantDock {
  static siteName = section?.dataset.siteName || "this site";

  static open(focus = true) {
    document.documentElement.classList.add("agent-dock-open");
    section.setAttribute("aria-hidden", "false");
    AssistantDock.launcher.setAttribute("aria-expanded", "true");
    remember(true);
    setTimeout(AssistantDock.badges, 320);
    if (focus) chatInput().then((input) => input?.focus({ preventScroll: true }));
  }

  static close() {
    document.documentElement.classList.remove("agent-dock-open");
    section.setAttribute("aria-hidden", "true");
    AssistantDock.launcher.setAttribute("aria-expanded", "false");
    AssistantDock.launcher.focus({ preventScroll: true });
    remember(false);
    setTimeout(AssistantDock.badges, 320);
  }

  /**
   * Open the panel and put a question in the chat. With send, press Send as well.
   * @param {string} text
   * @param {boolean} send
   */
  static FILL_TIP = "Fill in the form for me";

  /** The start of a sentence the visitor finishes, so the assistant gets the details at once. */
  static formStarter(title) {
    return title ? `Fill in the "${title}" form: ` : "Fill in the form: ";
  }

  static async ask(text, send = true) {
    AssistantDock.open(false);
    const input = await chatInput();
    if (!input) return;
    input.value = text;
    input.dispatchEvent(new Event("input", { bubbles: true }));
    input.focus({ preventScroll: true });
    input.setSelectionRange?.(text.length, text.length);
    const button = document.querySelector("#ns-send");
    if (send && button && !button.disabled) button.click();
  }

  /** The launcher, the close button and the panel classes. */
  static build() {
    // No slide on page load: the panel starts closed without animating there.
    section.style.transition = "none";
    section.classList.add("assistant--dock");
    requestAnimationFrame(() => requestAnimationFrame(() => { section.style.transition = ""; }));
    // Once connected, the status line has nothing more to say; it stays for screen readers on errors.
    const status = section.querySelector("#assistant-status");
    if (status) {
      const mark = () => section.classList.toggle("is-connected", /connected/i.test(status.textContent) && !/not|could/i.test(status.textContent));
      new MutationObserver(mark).observe(status, { childList: true, characterData: true, subtree: true });
      mark();
    }
    section.setAttribute("role", "complementary");
    section.setAttribute("aria-hidden", "true");

    const close = document.createElement("button");
    close.type = "button";
    close.className = "agent-dock__close";
    close.setAttribute("aria-label", "Close the assistant");
    close.innerHTML = '<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>';
    close.addEventListener("click", AssistantDock.close);
    // One top bar: the panel's name, New chat (moved here once the chat exists) and close.
    const bar = document.createElement("div");
    bar.className = "agent-dock__bar";
    const heading = section.querySelector("#assistant-heading");
    if (heading) bar.append(heading);
    bar.append(close);
    section.prepend(bar);
    AssistantDock.bar = bar;
    // The privacy note, in one short line at the bottom of the panel.
    const note = section.querySelector(".assistant-note");
    if (note) {
      note.title = note.textContent.trim();
      note.textContent = "AI answers from this site's pages. Your messages go to its AI provider, and nothing is sent without your OK.";
    }

    const launcher = document.createElement("button");
    launcher.type = "button";
    launcher.className = "agent-launcher";
    launcher.setAttribute("aria-controls", "assistant");
    launcher.setAttribute("aria-expanded", "false");
    launcher.innerHTML = `<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><path d="M12 3l1.8 4.9L19 9.7l-5.2 1.8L12 16.4l-1.8-4.9L5 9.7l5.2-1.8z" fill="currentColor"/><path d="M19 15l.8 2.2L22 18l-2.2.8L19 21l-.8-2.2L16 18l2.2-.8z" fill="currentColor"/></svg><span></span>`;
    launcher.querySelector("span").textContent = `Ask ${AssistantDock.siteName}`;
    launcher.addEventListener("click", () => AssistantDock.open());
    document.body.append(launcher);
    AssistantDock.launcher = launcher;

    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape" && document.documentElement.classList.contains("agent-dock-open") && !document.querySelector("dialog[open]")) AssistantDock.close();
    });
  }

  /**
   * Once the chat exists: New chat goes to the top bar, and a few suggested questions sit
   * above the input until the visitor sends their first message.
   * @param {object} placement
   */
  static decorate(placement = {}) {
    const newChat = document.querySelector("#ns-newchat");
    if (newChat) {
      newChat.removeAttribute("style");
      newChat.className = "agent-dock__new";
      AssistantDock.bar.insertBefore(newChat, AssistantDock.bar.querySelector(".agent-dock__close"));
    }
    const chat = section.querySelector(".ns-chat");
    const inputBar = section.querySelector(".ns-inputbar");
    if (!chat || !inputBar) return;
    const own = (placement.spots ?? []).flatMap((s) => s.ask?.questions ?? []);
    const kinds = new Set((placement.spots ?? []).map((s) => s.kind));
    const fallback = [
      ...(kinds.has("form") ? [AssistantDock.FILL_TIP] : []),
      ...(kinds.has("compare") ? ["Help me choose the right option."] : []),
    ];
    const list = [...new Set([...own, ...AssistantDock.questions(), ...fallback])].slice(0, 3);
    if (!list.length) return;
    const tips = document.createElement("div");
    tips.className = "agent-dock__tips";
    tips.setAttribute("aria-label", "Suggested questions");
    for (const q of list) {
      const b = document.createElement("button");
      b.type = "button";
      b.textContent = q;
      // The form tip only starts the sentence: the visitor says what to fill in.
      const formSpot = (placement.spots ?? []).find((s) => s.kind === "form");
      b.addEventListener("click", () => (q === AssistantDock.FILL_TIP
        ? AssistantDock.ask(AssistantDock.formStarter(formSpot?.title), false)
        : AssistantDock.ask(q, true)));
      tips.append(b);
    }
    chat.insertBefore(tips, inputBar);
    const msgs = section.querySelector("#ns-msgs");
    const update = () => { tips.hidden = !!msgs?.querySelector(".ns-msg.user"); };
    if (msgs) new MutationObserver(update).observe(msgs, { childList: true });
    update();
  }

  /** Number badges at the corner of each outlined part (drawn over the page, so no site layout changes). */
  static badges() {
    for (const b of document.querySelectorAll(".agent-badge")) b.remove();
    // The badge goes inside the part, in the page's own flow, so it stays with it however the
    // page moves (the panel opening, scrolling, resizing). One outlined part needs no number.
    const cited = document.querySelectorAll(".agent-cited[data-agent-n]");
    if (cited.length < 2) return;
    for (const el of cited) {
      const b = document.createElement("span");
      b.className = "agent-badge";
      b.setAttribute("aria-hidden", "true");
      b.textContent = el.getAttribute("data-agent-n");
      if (el.tagName === "TR") (el.querySelector("th, td") ?? el).prepend(b);
      else if (/^(INPUT|SELECT|TEXTAREA|BUTTON|IMG|A|TABLE)$/.test(el.tagName)) el.before(b);
      else el.prepend(b);
    }
  }

  /** Remove everything the assistant drew on the page: outlines, table marks, tour. */
  static clearPage() {
    for (const b of document.querySelectorAll(".agent-badge")) b.remove();
    for (const old of document.querySelectorAll(".agent-cited, .agent-cited--now")) { old.classList.remove("agent-cited", "agent-cited--now"); old.removeAttribute("data-agent-n"); }
    for (const el of document.querySelectorAll(".agent-row, .agent-col, .agent-table-focus")) el.classList.remove("agent-row", "agent-col", "agent-table-focus");
    AssistantDock.tour = null;
    document.documentElement.classList.remove("agent-tour");
    document.querySelector(".agent-coach")?.remove();
  }

  /**
   * A guided tour: every step outlined and numbered, and a note bubble at the current step
   * with Back and Next. One step with no title is a single note (used for tables).
   * @param {{title:string, steps:Array<{el:Element, note:string}>}} tour
   */
  static startTour(tour) {
    AssistantDock.clearPage();
    tour.steps.forEach((s, i) => { s.el.classList.add("agent-cited"); s.el.setAttribute("data-agent-n", String(i + 1)); });
    if (tour.steps.length > 1) AssistantDock.badges();
    AssistantDock.tour = { ...tour, at: 0 };
    document.documentElement.classList.toggle("agent-tour", tour.steps.length > 1);
    AssistantDock.showStep(0);
  }

  static showStep(at) {
    const tour = AssistantDock.tour;
    if (!tour) return;
    tour.at = Math.max(0, Math.min(at, tour.steps.length - 1));
    const step = tour.steps[tour.at];
    step.el.scrollIntoView({ behavior: matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth", block: "center" });
    let coach = document.querySelector(".agent-coach");
    if (!coach) {
      coach = document.createElement("div");
      coach.className = "agent-coach";
      coach.setAttribute("role", "dialog");
      document.body.append(coach);
    }
    const many = tour.steps.length > 1;
    coach.innerHTML = `
      <div class="agent-coach__top"><span class="agent-coach__n">${many ? `Step ${tour.at + 1} of ${tour.steps.length}` : "✦"}</span><b></b>
        <button type="button" class="agent-coach__x" aria-label="Close">×</button></div>
      <p></p>
      ${many ? `<div class="agent-coach__nav"><button type="button" data-step="-1" ${tour.at === 0 ? "disabled" : ""}>Back</button><button type="button" class="agent-coach__next" data-step="1">${tour.at === tour.steps.length - 1 ? "Done" : "Next"}</button></div>` : ""}`;
    coach.querySelector("b").textContent = tour.title || "";
    coach.querySelector("p").textContent = step.note;
    coach.setAttribute("aria-label", tour.title || "Note from the assistant");
    coach.querySelector(".agent-coach__x").addEventListener("click", AssistantDock.clearPage);
    for (const b of coach.querySelectorAll("[data-step]")) {
      b.addEventListener("click", () => {
        if (b.dataset.step === "1" && tour.at === tour.steps.length - 1) { coach.remove(); return; }
        AssistantDock.showStep(tour.at + Number(b.dataset.step));
      });
    }
    for (const el of document.querySelectorAll(".agent-cited")) el.classList.toggle("agent-cited--now", el === step.el);
    // The card sits at the bottom left of the screen (styles), and the step is scrolled to
    // the middle, so the card never covers the step or the steps around it.
    if (tour.steps.length > 1) AssistantDock.badges();
  }

  /**
   * Take the visitor to another page: a short countdown they can stop, then the page opens
   * with the part outlined, and the panel says why they are there.
   * @param {{url:string, path:string, reason:string}} go
   */
  static navigate(go) {
    document.querySelector(".agent-go")?.remove();
    const toast = document.createElement("div");
    toast.className = "agent-go";
    toast.setAttribute("role", "status");
    toast.innerHTML = '<span class="agent-go__bar"></span><span class="agent-go__text"></span><button type="button">Stay here</button>';
    toast.querySelector(".agent-go__text").textContent = `Taking you to ${go.path}…`;
    document.body.append(toast);
    const timer = setTimeout(() => {
      try { sessionStorage.setItem("mythagentic-arrival", JSON.stringify({ reason: go.reason, from: location.pathname })); } catch { /* the outline still shows */ }
      remember(true);
      location.href = go.url;
    }, 3000);
    toast.querySelector("button").addEventListener("click", () => { clearTimeout(timer); toast.remove(); });
  }

  /** After go_to_page: open the panel with a card saying why the visitor is here. */
  static arrived() {
    let arrival = null;
    try {
      arrival = JSON.parse(sessionStorage.getItem("mythagentic-arrival") || "null");
      sessionStorage.removeItem("mythagentic-arrival");
    } catch { /* nothing to show */ }
    if (!arrival?.reason) return;
    const card = document.createElement("div");
    card.className = "agent-arrival";
    card.innerHTML = '<b>↪ You\'re here because</b><span></span>';
    card.querySelector("span").textContent = arrival.reason;
    const chat = section.querySelector(".ns-chat");
    chat?.insertBefore(card, chat.querySelector("#ns-msgs") ?? chat.firstChild);
    AssistantDock.open(false);
  }

  /** An element's text with a space between elements, so table cells do not run together. */
  static spaced(el) {
    const parts = [];
    const walk = (n) => {
      if (n.nodeType === 3) parts.push(n.data);
      else if (n.nodeType === 1) { for (const c of n.childNodes) walk(c); parts.push(" "); }
    };
    walk(el);
    return parts.join("");
  }

  /** Lower-case word stems of four or more letters ("roses" → "rose", "lilies" → "lily"). */
  static stems(text) {
    // Words of four or more letters, and short codes in capitals such as "DMG" or "RTS".
    return String(text).split(/[^\p{L}\p{N}]+/u).filter((w) => w.length >= 4 || /^(?=.*[A-Z])[A-Z0-9]{2,}$/.test(w))
      .map((w) => w.toLowerCase().replace(/ies$/, "y").replace(/(?<=[^s])s$/, ""));
  }

  /**
   * The sources an answer used: those whose heading has a distinctive word (one that few
   * other headings share) that the answer also says. "White roses and purple tulips"
   * cites "What does a rose mean?" and "What does a tulip mean?", not "What does a lily mean?".
   * @param {string} answer
   * @param {Array<{url:string, heading:string}>} sources
   */
  static cited(answer, sources) {
    const said = new Set(AssistantDock.stems(answer));
    const unique = [...new Map(sources.map((s) => [`${s.url}#${s.heading}`, s])).values()];
    const df = new Map();
    for (const s of unique) for (const w of new Set(AssistantDock.stems(s.heading))) df.set(w, (df.get(w) ?? 0) + 1);
    const limit = Math.max(1, Math.ceil(unique.length * 0.2));
    const hits = [];
    for (const s of unique) {
      const words = [...new Set(AssistantDock.stems(s.heading))].filter((w) => df.get(w) <= limit);
      const matched = words.filter((w) => said.has(w)).length;
      if (matched > 0 && matched >= Math.min(2, words.length)) hits.push(s);
    }
    return hits.slice(0, 6);
  }

  /** Is this URL the page the visitor has open? */
  static here(url) {
    const strip = (p) => p.replace(/index\.html$/, "").replace(/\/$/, "");
    try {
      return strip(new URL(url, document.URL).pathname) === strip(location.pathname);
    } catch {
      return false;
    }
  }

  /** The element on this page for a heading or row text: its card when it has one. */
  static elementFor(heading) {
    const want = heading.replace(/\s+/g, " ").trim().toLowerCase();
    if (!want) return null;
    const main = document.querySelector("main") ?? document.querySelector("[role=main]") ?? document.body;
    for (const el of main.querySelectorAll("h1, h2, h3, h4, h5, summary, tr, dt, legend, label")) {
      if (el.closest("#assistant, .agent-hook")) continue;
      const own = el.textContent.replace(/\s+/g, " ").trim().toLowerCase();
      if (own !== want && !own.startsWith(want)) continue;
      if (el.tagName === "SUMMARY") return el.parentElement;
      const parent = el.parentElement;
      if (/^H[1-5]$/.test(el.tagName) && parent && parent !== main && parent.querySelector("h1, h2, h3, h4, h5") === el && parent.textContent.length < 2500) return parent;
      return el;
    }
    return null;
  }

  /** Outline the parts an answer used, numbered, and scroll to the first. */
  static point(elements) {
    for (const old of document.querySelectorAll(".agent-cited, .agent-cited--now")) { old.classList.remove("agent-cited", "agent-cited--now"); old.removeAttribute("data-agent-n"); }
    elements.forEach((el, i) => { el.classList.add("agent-cited"); el.setAttribute("data-agent-n", String(i + 1)); });
    if (elements.length > 1) AssistantDock.badges(); else for (const b of document.querySelectorAll(".agent-badge")) b.remove();
    if (elements[0]) elements[0].scrollIntoView({ behavior: matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth", block: "start" });
  }

  /**
   * Under each answer: where it comes from. Parts of this page are outlined and numbered;
   * other pages get a link that opens them with that part outlined.
   */
  static watchAnswers() {
    const msgs = section.querySelector("#ns-msgs");
    if (!msgs) return;
    let sources = [];
    let timer = 0;
    document.addEventListener("agent:sources", (event) => { sources.push(...event.detail); });
    const finish = () => {
      if (section.querySelector('.ns-inputbar[data-turn-active="true"]')) { timer = setTimeout(finish, 600); return; }
      AssistantDock.saveChat();
      const all = [...msgs.querySelectorAll(".ns-msg")];
      const lastUser = all.findLastIndex((m) => m.classList.contains("user"));
      const answer = all.slice(lastUser + 1).findLast((m) => m.classList.contains("bot"));
      if (lastUser < 0 || !answer || answer.dataset.agentPointed) return;
      answer.dataset.agentPointed = "1";
      // Rows of the tables on this page count too: an answer that names "DMG" points at its row.
      const rows = [];
      for (const table of (document.querySelector("main") ?? document.body).querySelectorAll("table")) {
        const trs = [...table.querySelectorAll("tr")].slice(1);
        if (trs.length > 40) continue;
        for (const tr of trs) {
          const first = tr.querySelector("th, td")?.textContent.replace(/\s+/g, " ").trim();
          if (first) rows.push({ url: document.URL, heading: first });
        }
      }
      const used = AssistantDock.cited(AssistantDock.spaced(answer), [...rows, ...sources]);
      if (!used.length) return;
      const onPage = [];
      const box = document.createElement("div");
      box.className = "agent-sources";
      const label = document.createElement("span");
      label.textContent = "Where it says so:";
      box.append(label);
      for (const s of used) {
        const el = AssistantDock.here(s.url) ? AssistantDock.elementFor(s.heading) : null;
        // The page's own title heading points at nothing in particular.
        if (el?.tagName === "H1") continue;
        // "What does a rose mean?" → "rose"; other headings stay as the site words them.
        const short = s.heading.replace(/^what does (an? |the )?(.+) mean\??$/i, "$2").slice(0, 60);
        if (el) {
          onPage.push(el);
          const n = onPage.length;
          const b = document.createElement("button");
          b.type = "button";
          b.innerHTML = `<b>${n}</b>`;
          b.append(` ${short}`);
          b.title = `Show "${s.heading}" on this page`;
          b.addEventListener("click", () => AssistantDock.point([el]));
          box.append(b);
        } else {
          const a = document.createElement("a");
          const url = new URL(s.url, document.URL);
          url.searchParams.set("show", s.heading);
          a.href = url.href;
          a.textContent = `↗ ${short}`;
          a.title = `Open the page with "${s.heading}"`;
          box.append(a);
        }
      }
      answer.after(box);
      // A guided tour keeps its steps; a single note (such as on a table) keeps its note,
      // and the parts the answer named are outlined too.
      if (onPage.length && (!AssistantDock.tour || AssistantDock.tour.steps.length === 1)) AssistantDock.point(onPage);
    };
    new MutationObserver((records) => {
      for (const r of records) {
        for (const n of r.addedNodes) {
          if (n.nodeType === 1 && n.classList?.contains("ns-msg") && n.classList.contains("user")) {
            sources = [];
            AssistantDock.clearPage();
          }
        }
      }
      clearTimeout(timer);
      timer = setTimeout(finish, 700);
    }).observe(msgs, { childList: true, subtree: true, characterData: true });
  }

  /** A link from an answer on another page (?show=heading): outline that part here. */
  static showFromUrl() {
    const heading = new URL(document.URL).searchParams.get("show");
    if (!heading) return;
    const el = AssistantDock.elementFor(heading);
    if (el) setTimeout(() => AssistantDock.point([el]), 300);
  }

  /**
   * The runtime keeps the conversation only in the open page's memory, so moving to another
   * page of the site started a new chat. The conversation is kept for this browser tab
   * (sessionStorage): what the visitor sees, and the turns the model remembers.
   */
  static chatKey = `mythagentic-chat:${new URL("./", import.meta.url).pathname}`;

  /** The runtime engine, from site.js (the same module the page loaded). */
  static async engine() {
    try {
      const { AssistantMount } = await import(new URL("site.js", import.meta.url).href);
      return AssistantMount.engine ?? null;
    } catch {
      return null;
    }
  }

  static async saveChat() {
    const msgs = section.querySelector("#ns-msgs");
    const engine = await AssistantDock.engine();
    if (!msgs || !engine) return;
    const shown = [...msgs.querySelectorAll(".ns-msg")]
      .filter((m) => !m.classList.contains("ns-turn-status") && m.dataset.welcome !== "true" && m !== msgs.firstElementChild)
      .map((m) => ({ role: m.classList.contains("user") ? "user" : "bot", html: m.classList.contains("user") ? "" : m.innerHTML, text: m.textContent }))
      .slice(-30);
    try {
      sessionStorage.setItem(AssistantDock.chatKey, JSON.stringify({ shown, history: (engine.history ?? []).slice(-24) }));
    } catch { /* storage full or blocked: the chat still works on this page */ }
  }

  static async restoreChat() {
    const msgs = section.querySelector("#ns-msgs");
    document.querySelector("#ns-newchat")?.addEventListener("click", () => {
      try { sessionStorage.removeItem(AssistantDock.chatKey); } catch { /* nothing kept */ }
    });
    let saved = null;
    try { saved = JSON.parse(sessionStorage.getItem(AssistantDock.chatKey) || "null"); } catch { /* none */ }
    if (!msgs || !saved?.shown?.length) return;
    const engine = await AssistantDock.engine();
    if (engine && Array.isArray(saved.history) && engine.history.length === 0) engine.history.push(...saved.history);
    for (const m of saved.shown) {
      const div = document.createElement("div");
      div.className = m.role === "user" ? "ns-msg user" : "ns-msg bot ns-rich";
      // Restored answers were already pointed at on their own page.
      div.dataset.agentPointed = "1";
      if (m.role === "user") div.textContent = m.text;
      else div.innerHTML = m.html;
      msgs.append(div);
    }
    const note = document.createElement("div");
    note.className = "agent-carried";
    note.textContent = "Your conversation continues from the last page.";
    msgs.append(note);
    msgs.scrollTop = msgs.scrollHeight;
  }

  /** Question headings on this page, in order, for the Ask bar's suggestions. */
  static questions() {
    const main = document.querySelector("main") ?? document.querySelector("[role=main]") ?? document.body;
    return [...main.querySelectorAll("h1, h2, h3, h4, summary")]
      .filter((h) => !h.closest("#assistant, .agent-hook"))
      .map((h) => h.textContent.replace(/\s+/g, " ").trim())
      .filter((t) => t.endsWith("?") && t.length <= 90);
  }

  /** placement.json, for the owner's own Ask bar words (spot.ask); {} when it cannot load. */
  static async placement() {
    try {
      const res = await fetch(new URL("placement.json", import.meta.url), { cache: "no-store" });
      return res.ok ? await res.json() : {};
    } catch {
      return {};
    }
  }

  /** One Ask bar before each marked part of the page. */
  static hooks(placement = {}) {
    const asks = Object.fromEntries((placement.spots ?? []).filter((s) => s.ask).map((s) => [s.id, s.ask]));
    for (const target of document.querySelectorAll("[data-agent-spot]")) {
      const kind = target.dataset.agentKind;
      const own = asks[target.dataset.agentSpot];
      const bar = document.createElement("div");
      bar.className = "agent-hook";
      bar.setAttribute("role", "group");
      bar.setAttribute("aria-label", `Ask ${AssistantDock.siteName}`);
      const head = document.createElement("div");
      head.className = "agent-hook__head";
      head.innerHTML = '<span class="agent-hook__spark" aria-hidden="true">✦</span><b></b><span class="agent-hook__sub"></span>';
      const actions = document.createElement("div");
      actions.className = "agent-hook__actions";
      const button = (label, onClick, primary = false) => {
        const b = document.createElement("button");
        b.type = "button";
        b.className = primary ? "agent-hook__btn agent-hook__btn--primary" : "agent-hook__btn";
        b.textContent = label;
        b.addEventListener("click", onClick);
        actions.append(b);
      };
      if (kind === "form") {
        head.querySelector("b").textContent = "Let the assistant fill this in";
        head.querySelector(".agent-hook__sub").textContent = "Say it in one sentence. It fills the form below and asks you before anything is sent.";
        // Starts the sentence in the chat box; the visitor finishes it with their details.
        const title = (placement.spots ?? []).find((s) => s.id === target.dataset.agentSpot)?.title;
        button("Fill it with the assistant", () => AssistantDock.ask(AssistantDock.formStarter(title), false), true);
      } else if (kind === "compare") {
        head.querySelector("b").textContent = "Not sure which one?";
        head.querySelector(".agent-hook__sub").textContent = "Tell the assistant what matters to you. It compares the rows below.";
        button("Help me choose", () => AssistantDock.ask("Help me choose from this table. Ask me what matters to me.", true), true);
      } else {
        head.querySelector("b").textContent = "Ask instead of scrolling";
        head.querySelector(".agent-hook__sub").textContent = "The assistant answers from this site and shows you where it says so.";
        for (const q of AssistantDock.questions().slice(0, 3)) button(q, () => AssistantDock.ask(q, true));
        button("Ask your own question", () => AssistantDock.ask("", false), true);
      }
      if (own) {
        // The owner's words replace the defaults; the main button stays.
        if (own.title) head.querySelector("b").textContent = own.title;
        if (own.sub) head.querySelector(".agent-hook__sub").textContent = own.sub;
        if (own.questions?.length) {
          for (const b of [...actions.querySelectorAll(".agent-hook__btn:not(.agent-hook__btn--primary)")]) b.remove();
          const primary = actions.querySelector(".agent-hook__btn--primary");
          for (const q of own.questions) {
            const b = document.createElement("button");
            b.type = "button";
            b.className = "agent-hook__btn";
            b.textContent = q;
            b.addEventListener("click", () => AssistantDock.ask(q, true));
            actions.insertBefore(b, primary);
          }
        }
      }
      bar.append(head, actions);
      target.before(bar);
    }
  }

  static async start() {
    if (!section) return;
    const brand = brandColour();
    if (brand) document.documentElement.style.setProperty("--agent-brand", brand);
    AssistantDock.build();
    const placement = await AssistantDock.placement();
    AssistantDock.hooks(placement);
    document.addEventListener("agent:tour", (event) => AssistantDock.startTour(event.detail));
    let resized = 0;
    addEventListener("resize", () => {
      clearTimeout(resized);
      resized = setTimeout(() => { AssistantDock.badges(); if (AssistantDock.tour) AssistantDock.showStep(AssistantDock.tour.at); }, 150);
    });
    document.addEventListener("agent:navigate", (event) => AssistantDock.navigate(event.detail));
    chatInput(20000).then(async (input) => {
      if (!input) return;
      AssistantDock.decorate(placement);
      await AssistantDock.restoreChat();
      AssistantDock.watchAnswers();
      AssistantDock.arrived();
    });
    AssistantDock.showFromUrl();
    if (remembered()) AssistantDock.open(false);
  }
}

await AssistantDock.start();
